A small fixed-capacity ring buffer, used for a moving average over sensor samples. C++20, no heap allocation.

```cpp
#include <array>
#include <cstddef>
#include <iomanip>
#include <iostream>
#include <optional>
#include <utility>

template <typename T, std::size_t N>
class RingBuffer {
    static_assert(N > 0, "RingBuffer capacity must be at least 1");

public:
    // Returns false if the buffer is full.
    bool push(T value) {
        if (full()) return false;
        data_[(head_ + size_) % N] = std::move(value);
        ++size_;
        return true;
    }

    // Always succeeds; drops the oldest element when full.
    void push_overwrite(T value) {
        data_[(head_ + size_) % N] = std::move(value);
        if (full())
            head_ = (head_ + 1) % N;
        else
            ++size_;
    }

    std::optional<T> pop() {
        if (empty()) return std::nullopt;
        T value = std::move(data_[head_]);
        head_ = (head_ + 1) % N;
        --size_;
        return value;
    }

    // Index 0 is the oldest element.
    const T& operator[](std::size_t i) const { return data_[(head_ + i) % N]; }

    [[nodiscard]] std::size_t size() const noexcept { return size_; }
    [[nodiscard]] bool empty() const noexcept { return size_ == 0; }
    [[nodiscard]] bool full() const noexcept { return size_ == N; }
    static constexpr std::size_t capacity() noexcept { return N; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

template <typename T, std::size_t N>
double average(const RingBuffer<T, N>& buf) {
    if (buf.empty()) return 0.0;
    double sum = 0.0;
    for (std::size_t i = 0; i < buf.size(); ++i)
        sum += buf[i];
    return sum / static_cast<double>(buf.size());
}

int main() {
    constexpr std::array samples{10.0, 12.0, 11.0, 50.0, 13.0, 12.0, 11.0, 10.0};
    RingBuffer<double, 4> window;

    std::cout << std::fixed << std::setprecision(2);
    for (double s : samples) {
        window.push_overwrite(s);
        std::cout << "sample " << std::setw(6) << s
                  << "  avg(" << window.size() << ") = " << average(window) << '\n';
    }

    std::cout << "\ndraining:";
    while (auto v = window.pop())
        std::cout << ' ' << *v;
    std::cout << '\n';
}
```

Build and run:

```bash
g++ -std=c++20 -Wall -Wextra -O2 ring.cpp -o ring && ./ring
```

A few deliberate choices: `std::array` keeps it allocation-free (fine for embedded or real-time loops), `pop()` returns `std::optional` instead of throwing, and the `50.0` spike shows how a 4-sample window smears an outlier across four outputs before it ages out.
